class Solution { public: int scoreOfStudents(string s,vector<int>& answers){int count=(s.size()+1)/2;vector<int> numbers(count);vector<char> operators(count-1);for(int i=0;i<count;++i){numbers[i]=s[2*i]-'0';if(i+1<count)operators[i]=s[2*i+1];}int correct=0,term=numbers[0];for(int i=0;i<(int)operators.size();++i)if(operators[i]=='*')term*=numbers[i+1];else{correct+=term;term=numbers[i+1];}correct+=term;vector<vector<set<int>>> dp(count,vector<set<int>>(count));for(int i=0;i<count;++i)dp[i][i].insert(numbers[i]);for(int length=2;length<=count;++length)for(int left=0;left+length<=count;++left){int right=left+length-1;for(int split=left;split<right;++split)for(int a:dp[left][split])for(int b:dp[split+1][right]){int value=operators[split]=='+'?a+b:a*b;if(value<=1000)dp[left][right].insert(value);}}int score=0;for(int answer:answers)score+=answer==correct?5:dp[0][count-1].count(answer)?2:0;return score;} };
